object compositeKeyParent extends TableDef("composite_key_parent") {
  val key1 = col("key_1", int4)
  val key2 = col("key_2", varchar)
}
object compositeKeyChild extends TableDef("composite_key_child") {
  val id      = col("id", int4)
  val parent1 = col("parent_1", int4)
  val parent2 = col("parent_2", varchar)
}

ObjectMapping(
  tpe = ParentType,
  fieldMappings = List(
    SqlField("key1", compositeKeyParent.key1, key = true),
    SqlField("key2", compositeKeyParent.key2, key = true),
    SqlObject("children", Join(List(
      (compositeKeyParent.key1, compositeKeyChild.parent1),
      (compositeKeyParent.key2, compositeKeyChild.parent2)
    )))
  )
)

SqlInterfaceMapping(
  tpe = EType,                       // interface Entity
  discriminator = entityTypeDiscriminator,
  fieldMappings = List(
    SqlField("id", entities.id, key = true),
    SqlField("entityType", entities.entityType, discriminator = true),
    SqlField("title", entities.title),
    SqlObject("synopses")
  )
),
ObjectMapping(                       // type Film implements Entity
  tpe = FilmType,
  fieldMappings = List(
    SqlField("rating", entities.filmRating),
    SqlField("label",  entities.filmLabel),
    SqlField("imageUrl", entities.imageUrl)
  )
)

lazy val entityTypeDiscriminator = new SqlDiscriminator {
  def discriminate(c: Cursor): Result[Type] =
    c.fieldAs[EntityType]("entityType").map {
      case EntityType.Film   => FilmType
      case EntityType.Series => SeriesType
    }
  def narrowPredicate(subtpe: Type): Result[Predicate] = subtpe match {
    case FilmType   => Eql(EType / "entityType", Const(EntityType.Film)).success
    case SeriesType => Eql(EType / "entityType", Const(EntityType.Series)).success
    case _ => Result.internalError(s"Invalid discriminator: $subtpe")
  }
}

object collections extends TableDef("collections") {
  val id       = col("id", text)
  val itemType = col("item_type", text)
  val itemA    = col("itema", text)
  val itemB    = col("itemb", text)
}

SqlUnionMapping(
  tpe = ItemType,                    // union Item = ItemA | ItemB
  discriminator = itemTypeDiscriminator,
  fieldMappings = List(
    SqlField("id", collections.id, key = true, hidden = true),
    SqlField("itemType", collections.itemType, discriminator = true, hidden = true)
  )
),
ObjectMapping(tpe = ItemAType, fieldMappings = List(
  SqlField("id", collections.id, key = true, hidden = true),
  SqlField("itema", collections.itemA)
)),
ObjectMapping(tpe = ItemBType, fieldMappings = List(
  SqlField("id", collections.id, key = true, hidden = true),
  SqlField("itemb", collections.itemB)
))

object itemTypeDiscriminator extends SqlDiscriminator {
  def discriminate(c: Cursor): Result[Type] =
    c.fieldAs[String]("itemType").map { case "ItemA" => ItemAType; case "ItemB" => ItemBType }
  def narrowPredicate(subtpe: Type): Result[Predicate] = subtpe match {
    case ItemAType => Eql(ItemType / "itemType", Const("ItemA")).success
    case ItemBType => Eql(ItemType / "itemType", Const("ItemB")).success
    case _ => Result.internalError(s"Invalid discriminator: $subtpe")
  }
}

object records extends TableDef("records") {
